"use strict";(self.webpackChunkajaymore=self.webpackChunkajaymore||[]).push([["1616"],{592(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>n,default:()=>u,frontMatter:()=>s,metadata:()=>i,toc:()=>l});var i=o(9875),a=o(4848),r=o(8453);let s={title:"Where is my weekend?",date:new Date("2014-04-13T11:07:36.000Z"),authors:["ajay"],tags:["Work","ethics"],description:"Currently there is an epidemic that has gripped the IT industry. The epidemic called weekend working. The disease that has left thousands stressful, depressed and unhappy. There is a huge number of smart, hardworking individuals who are exposed to this new way of slave labour. People are forced to forgo the desire to bond with\u2026",image:"./6a00d83420a27c53ef00e550676b738833-800wi.png",mdx:{format:"md"}},n,h={image:o(1427).A,authorsImageUrls:[void 0]},l=[];function d(e){let t={a:"a",br:"br",em:"em",li:"li",ol:"ol",p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["Currently there is an epidemic that has gripped the IT industry. The epidemic called weekend working. The disease that has left thousands stressful, depressed and unhappy. There is a huge number of smart, hardworking individuals who are exposed to this new way of slave labour. People are forced to forgo the desire to bond with their families, people are coerced to give up their priorities in life and focus on only single objective: saving their only job. There are numerous disgruntled employees who prefer countless hours of gossip at their desks instead of few productive hours of actual work. This may not be the case at every organization out there, but potentially it\u2019s ",(0,a.jsxs)(t.em,{children:["\u2018",(0,a.jsx)(t.em,{children:"THE CASE"}),"\u2018"]})," at every organization. When things go wrong weekend work is the first solution that appears. Nobody thinks it is unethical to take away people\u2019s moral right to get rest and rejuvenate themselves. Managers instill a sense of guilt into the minds of employees from the very beginning of the project, virtually scaring them off with warnings like: \u201Cnobody likes to work on a weekend, you guys better complete your tasks on time and we will never call you over the weekend\u201D. So if at all people are required to work weekends, it\u2019s their own fault as they did not give proper attention to the manager\u2019s prophecy."]}),"\n","\n",(0,a.jsx)(t.p,{children:"Yes I agree, there might be a critical situation where weekend work is the only solution. But if not defined within legal framework or as a matter of policy, then the critical situation becomes a matter of perspective. A weak project manager who is easily scared by the client will turn almost any adversity into a critical matter. I have seen people work weekends at almost all phases of software development. The criticality of the situation is almost always overblown. Weekend work is an easy excuse of the offshore managers for their incompetency. It gives them an argument that says \u201CI am getting my team to work 10-11 hours a day, I am getting them to work over weekends. What more do you expect of me. Things are difficult here, there is very little that is in my hands.\u201D The managers themselves are typical victims of this viciousness. There is no tyranny here, everyone suffers equally. Be it the manager or the employee. The manager\u2019s have to save their job too. The higher management cares very little, they often think people down the hierarchy are usually lazy and do not understand the gravity of the situation. There is wrong sense of pride in upper management who firmly believe that it\u2019s their interfacing with the client that brings million dollar projects, and it\u2019s the job of managers and developers to complete the project in stipulated time, let whatever be the difficulty. I totally agree with the first part, but it\u2019s the second part that bothers me. Let whatever be the difficulty! This thinking has given rise to a sort of moral degradation which eventually results in forcing people to work for 2-3 weeks without a day of rest."}),"\n",(0,a.jsx)(t.p,{children:"I classify the IT working population into 5 categories based on their likeliness to agree over working a weekend."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"Freshers (New joinees)"}),"\n",(0,a.jsx)(t.li,{children:"\xa0People with vested interest (onsite deputation, promotions, good grades)"}),"\n",(0,a.jsx)(t.li,{children:"The gullible, people who cannot say no to authority."}),"\n",(0,a.jsx)(t.li,{children:"The responsible (Married, debt ridden etc.)"}),"\n",(0,a.jsx)(t.li,{children:"Free spirits. (The I don\u2019t give a damn types)"}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["The responsible and the free spirits are the only ones who oppose the system of weekend work. The rest are either confused or leave it for others to fight, they are okay either ways. It\u2019s a classic psychology game. If anyone agrees to work over a weekend, then the managers use their example to coerce others. If a junior agrees then a senior is obliged as a sense of responsibility. If a senior agrees then junior has to agree as who knows better than a senior. Managers are pretty good at this game. Few who oppose cannot do so forever as they start suffering from ",(0,a.jsx)(t.a,{href:"http://en.wikipedia.org/wiki/Cognitive_dissonance",children:"cognitive dissonance"}),", Their rational minds asks them to change their opinion by giving reasons of responsibility, obligation, guilt, team work and what not. It\u2019s really difficult to take a stand that you won\u2019t work under unethical conditions when all about you have given up. The major blame for weekend work culture lies on the individuals, who are either too naive to think about their own well-being or are to messed up in the responsibilities of the life. Either way we don\u2019t understand, what constitutes a good work ethic. Nobody talks about weekend work as a matter of right and wrong but instead confuse it with unwarranted situation."]}),"\n",(0,a.jsx)(t.p,{children:"The strong motive for writing this article comes from the psychological and physical impact weekend work has on the minds of the employees."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"Weekend work sends a message into the subconscious of individuals that their life is not in their control, they are overworked, and do not have time for simple pleasures of life. Sometimes even though they have plenty of time, they cannot muster up enough energy to get rid of the inertia created by those senseless visits to the office for no reason."}),"\n",(0,a.jsx)(t.li,{children:"People who work weekends rarely do any kind of physical activity during those times. As such people prefer not to workout even when their lives are okay. Weekend workers don\u2019t feel guilty for abusing their body since they feel trapped and lost. The thought of exercise appears ridiculous compared to the ordeal one is facing. Thus they compromise their health, which might lead to serious disease in near\xa0foreseeable\xa0future."}),"\n",(0,a.jsx)(t.li,{children:"People become absolutely inefficient and notoriously gossipy at work. I will bet more time is spent on gossip than actual work. That\u2019s the only creative haven they can resort to and employees use it in all perfection to get rid of their daily stress."}),"\n",(0,a.jsx)(t.li,{children:"There is a change in attitude weekend work instils a strong dislike towards the organization, superiors and in lots of cases dislike towards the work which is a major blow to person\u2019s individual growth."}),"\n",(0,a.jsx)(t.li,{children:"Family life is disturbed. People cannot take time off to take care of their loved ones. There are cases where people get called from hospitals, when their loved ones are in intensive care. There are plenty of examples where newly married couples have had the worst times of their life when their marriage just got started."}),"\n",(0,a.jsx)(t.li,{children:"While you work on weekends there are no plans, no recreational leaves, you are no more master of your life. The very tenets of freedom are killed right there. And nobody makes any fuss about it."}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["Like many of my colleagues I am not aware of labour laws. Did a bit of googling, but couldn\u2019t find laws that address this hairy issue.",(0,a.jsx)(t.br,{}),"\nCompanies provide an alternative week off by way of their policies towards a weekend worked. But that\u2019s not right as people volunteer (although not true \u{1F61B} ) to give up their time of comfort, in order to address the difficult times the project is facing. So they should be paid in a better fashion. The irresponsible company in one case doesn\u2019t even manage the transportation of the employee, and the individual has to cough up his own money to work over weekends, which is more humiliating. Besides thrifty remuneration, the week off itself isn\u2019t any good. I have seen people accumulate week offs to the count of 12-15 in a span of 4 months. Which is a half of their total weekends during that duration. In those times they do not get to enjoy their own paid leaves or public holidays even. There is a blatant abuse of law. People have worked on national holidays and Labor Day at times. What\u2019s more concerning is that the employee accumulates all these leaves which he cannot take and they eventually lapse off, unless off course somebody is allowed to take a big long vacation, which again is a rare case."]}),"\n",(0,a.jsx)(t.p,{children:"Some people may prefer good remuneration for working over weekends or working extra hours at office, as is the case in developed countries. But if you ask me I will say it\u2019s a slice of your precious life that you offer for nothing. Our jobs are means to an end, in case they are not what we wanted them to be. But our time away from that place of work is our opportunity to be better family members, better citizens, better intellectuals and better friends. It\u2019s that time of leisure which makes us more interesting person, if we are missing on that then what life are we leading?"})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},1427(e,t,o){o.d(t,{A:()=>i});let i=o.p+"assets/images/6a00d83420a27c53ef00e550676b738833-800wi-98da2ff462fc771b531278b001d0915b.png"},8453(e,t,o){o.d(t,{R:()=>s,x:()=>n});var i=o(6540);let a={},r=i.createContext(a);function s(e){let t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function n(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(r.Provider,{value:t},e.children)}},9875(e){e.exports=JSON.parse('{"permalink":"/blog/2014/04/13/where-is-my-weekend","source":"@site/blog/2014-04-13-where-is-my-weekend/index.md","title":"Where is my weekend?","description":"Currently there is an epidemic that has gripped the IT industry. The epidemic called weekend working. The disease that has left thousands stressful, depressed and unhappy. There is a huge number of smart, hardworking individuals who are exposed to this new way of slave labour. People are forced to forgo the desire to bond with\u2026","date":"2014-04-13T11:07:36.000Z","tags":[{"inline":true,"label":"Work","permalink":"/blog/tags/work"},{"inline":true,"label":"ethics","permalink":"/blog/tags/ethics"}],"readingTime":7.25,"hasTruncateMarker":true,"authors":[{"name":"Ajay More","title":"Maintainer of ajaymore.in","url":"https://github.com/ajaymore","imageURL":"https://avatars.githubusercontent.com/u/7659804?v=4","key":"ajay","page":null}],"frontMatter":{"title":"Where is my weekend?","date":"2014-04-13T11:07:36.000Z","authors":["ajay"],"tags":["Work","ethics"],"description":"Currently there is an epidemic that has gripped the IT industry. The epidemic called weekend working. The disease that has left thousands stressful, depressed and unhappy. There is a huge number of smart, hardworking individuals who are exposed to this new way of slave labour. People are forced to forgo the desire to bond with\u2026","image":"./6a00d83420a27c53ef00e550676b738833-800wi.png","mdx":{"format":"md"}},"unlisted":false,"prevItem":{"title":"The art of programming","permalink":"/blog/2014/04/22/the-art-of-programming"},"nextItem":{"title":"10 pounds lighter","permalink":"/blog/2014/03/21/10-pounds-lighter"}}')}}]);